JSONX_FUNCTION = 'def build_verdict(obj, item, threshold):\n    model_verdict = str(obj.get("verdict", "")).strip().lower()\n    if model_verdict not in ("pass", "fail"):\n        raise ValueError(f"verdict 非法：{obj.get(\'verdict\')!r}")\n    rules = as_list(obj.get("rules_hit"))\n    scores = obj.get("rubric_scores")\n    if not isinstance(scores, dict):\n        scores = {}\n    norm = obj.get("normalized_score")\n    if norm is None and scores:\n        vals = []\n        for value in scores.values():\n            try:\n                vals.append(float(value))\n            except Exception:\n                pass\n        if vals:\n            norm = sum(vals) / (2.0 * len(vals))\n    if norm is not None:\n        try:\n            norm = float(norm)\n        except Exception:\n            norm = None\n    norm = clamp01(norm) if norm is not None else None\n\n    # hard 只认模型显式字段。旧逻辑把“无 rubric 的 fail”自动视为 hard，\n    # 会把独立核查中的软失败变成高置信误杀。\n    hard_hit = bool(obj.get("hard_rule_hit"))\n    critic_verdict = str(obj.get("critic_verdict", "")).strip().lower()\n    independent_verdict = str(obj.get("independent_verdict", "")).strip().lower()\n    if critic_verdict not in ("pass", "fail", "not_applicable"):\n        critic_verdict = "not_applicable" if not scores and not rules else model_verdict\n    if independent_verdict not in ("pass", "fail"):\n        independent_verdict = model_verdict\n    coverage = clamp01(obj.get("evidence_coverage", 0.5 if norm is None else 1.0))\n    direct_error = bool(obj.get("independent_direct_error"))\n\n    # 最终聚合由代码执行，避免模型给出与两个子判决不一致的 verdict。\n    if hard_hit:\n        verdict = "fail"\n    elif critic_verdict == "fail" and independent_verdict == "fail":\n        verdict = "fail"\n    elif independent_verdict == "fail" and direct_error and coverage >= 0.8:\n        verdict = "fail"\n    else:\n        verdict = "pass"\n    disagreement = bool(obj.get("disagreement")) or (\n        critic_verdict in ("pass", "fail") and critic_verdict != independent_verdict\n    ) or verdict != model_verdict\n\n    # confidence 由可校准信号推导，不采信模型自报。无 rubric 时最多 0.5；\n    # 两条路径分歧时封顶 0.35，以便优先进入审计。\n    if norm is None:\n        confidence = round(0.5 * coverage, 2)\n    else:\n        margin = min(1.0, abs(norm - threshold) / 0.2)\n        confidence = round(margin * (0.5 + 0.5 * coverage), 2)\n    if hard_hit:\n        confidence = max(confidence, 0.9)\n    if disagreement and not hard_hit:\n        confidence = min(confidence, 0.35)\n\n    reason = str(obj.get("reason", ""))[:600]\n    return {\n        "item": item,\n        "verdict": verdict,\n        "model_verdict": model_verdict,\n        "verdict_corrected": verdict != model_verdict,\n        "hard_rule_hit": hard_hit,\n        "rules_hit": rules,\n        "rubric_scores": scores,\n        "normalized_score": norm,\n        "critic_verdict": critic_verdict,\n        "independent_verdict": independent_verdict,\n        "independent_direct_error": direct_error,\n        "disagreement": disagreement,\n        "evidence_coverage": coverage,\n        "applicable_critics": as_list(obj.get("applicable_critics")),\n        "confidence": confidence,\n        "reason": reason,\n    }\n'
POOL_FUNCTION = 'def cmd_audit_queue(a):\n    audited = set()\n    audited_path = Path(a.audited)\n    if audited_path.exists():\n        raw = audited_path.read_text(encoding="utf-8").strip()\n        if raw:\n            try:\n                obj = json.loads(raw)\n            except json.JSONDecodeError:\n                obj = None\n            if isinstance(obj, list):\n                for value in obj:\n                    if isinstance(value, str):\n                        audited.add(value)\n                    elif isinstance(value, dict) and value.get("dedup_key"):\n                        audited.add(str(value["dedup_key"]))\n            elif isinstance(obj, dict):\n                for value in obj.get("audited", []):\n                    audited.add(str(value))\n            else:\n                for line in raw.splitlines():\n                    row = json.loads(line)\n                    if isinstance(row, str):\n                        audited.add(row)\n                    elif isinstance(row, dict) and row.get("dedup_key"):\n                        audited.add(str(row["dedup_key"]))\n    verdicts = []\n    with open(a.verdicts, encoding="utf-8") as f:\n        for line in f:\n            line = line.strip()\n            if line:\n                verdicts.append(json.loads(line))\n\n    fresh_all = [v for v in verdicts\n                 if f\'{v["item"]}@static\' not in audited\n                 and f\'{v["item"]}@{a.fingerprint}\' not in audited]\n\n    def has_truth(v):\n        if a.allow_redo_as_truth or not (a.checker_dir or a.truth_dir):\n            return True\n        item = v["item"]\n        checker = os.path.join(a.checker_dir, item + ".sh") if a.checker_dir else ""\n        truth = os.path.join(a.truth_dir, item + ".md") if a.truth_dir else ""\n        return (checker and os.path.isfile(checker) and os.access(checker, os.X_OK)) \\\n            or (truth and os.path.isfile(truth))\n\n    fresh = [v for v in fresh_all if has_truth(v)]\n    skipped_no_truth = len(fresh_all) - len(fresh)\n    passes = sorted((v for v in fresh if v["verdict"] == "pass"),\n                    key=lambda v: (v.get("confidence", 0), v["item"]))\n    fails = sorted((v for v in fresh if v["verdict"] == "fail"),\n                   key=lambda v: (v.get("confidence", 0), v["item"]))\n\n    b = max(0, a.budget)\n    segment_order = ("fail-low", "pass-low", "fail-high", "pass-random")\n    base, extra = divmod(b, len(segment_order))\n    targets = {name: base + (i < extra)\n               for i, name in enumerate(segment_order)}\n    selected = []\n    selected_ids = set()\n\n    def take(seq, n, segment):\n        taken = 0\n        for v in seq:\n            if taken >= n:\n                break\n            if v["item"] in selected_ids:\n                continue\n            selected.append((v, segment))\n            selected_ids.add(v["item"])\n            taken += 1\n\n    take(fails, targets["fail-low"], "fail-low")\n    take(reversed(fails), targets["fail-high"], "fail-high")\n    take(passes, targets["pass-low"], "pass-low")\n    remaining_passes = [v for v in passes if v["item"] not in selected_ids]\n    random.seed(a.round)\n    random.shuffle(remaining_passes)\n    take(remaining_passes, targets["pass-random"], "pass-random")\n\n    remaining = [v for v in sorted(fresh, key=lambda x: x["item"])\n                 if v["item"] not in selected_ids]\n    random.seed(a.round + 1000003)\n    random.shuffle(remaining)\n    for v in remaining:\n        if len(selected) >= b:\n            break\n        segment = "fail-low" if v["verdict"] == "fail" else "pass-random"\n        selected.append((v, segment))\n        selected_ids.add(v["item"])\n\n    counts = {k: 0 for k in ("fail-low", "fail-high", "pass-low", "pass-random")}\n    for v, segment in selected[:b]:\n        counts[segment] += 1\n        print(json.dumps({"item": v["item"], "segment": segment}, ensure_ascii=False))\n    print("队列：" + " + ".join(f"{k} {counts[k]}" for k in counts)\n          + f"（预算 {b}，剔除已审 {len(verdicts) - len(fresh_all)} 条，"\n            f"无 checker/truth {skipped_no_truth} 条）", file=sys.stderr)\n'
VERIFY_PROMPT = 'write_prompt() {\n  cat > "$1" <<EOF\n你是 VeriSkill 的判别器 D。你只允许读取当前工作目录里的：\n- traj.md（必要时 traj.full.md）：待判轨迹\n- critics/：当前 D 技能库\n\n禁止读取或猜测 checker、truth、Oracle 输出、审计标签、其他条目的结果。\n你的职责是判断轨迹里的答案和过程是否有可直接证实的问题。证据不足不等于错误；\n不要因为轨迹简短、未展示全部中间步骤或看不出技能使用痕迹就判 fail。\n\n按固定流程执行：\n1. 读取 critics/，挑出适用 critic，把文件名写入 applicable_critics；没有则给空数组。\n2. 执行适用 critic 的规则。只有轨迹中的可观察证据明确满足触发条件时才命中；\n   执行不了、证据缺失或结论不明确都不命中。命中 [hard] 时\n   hard_rule_hit=true；命中 [soft] 时只写入 rules_hit。\n3. 没有命中 hard 时，按评分细则逐项打 0/1/2 分。\n   normalized_score = 总分 / (2 * 项数)。低于 ${THRESHOLD} 时\n   critic_verdict=fail，否则为 pass。没有适用 critic 时\n   critic_verdict=not_applicable、rubric_scores={}、normalized_score=null。\n4. 独立核查：只检查可由轨迹直接证实的重算不符、引用与原始证据矛盾、\n   单位/口径冲突或答非所问。给 independent_verdict，并给\n   evidence_coverage（0 到 1），表示实际覆盖关键结论的比例。\n5. 保守聚合：\n   - hard 命中 -> fail；\n   - critic 与独立核查都 fail -> fail；\n   - 仅独立核查 fail 时，必须有可定位直接错误且 evidence_coverage>=0.8 才 fail；\n   - 仅 critic fail 时 -> pass，disagreement=true，交给审计；\n   - 无适用 critic 时按独立核查的直接证据门槛决定。\n\n只输出一个 JSON 对象，不要输出代码围栏或其他文字：\n{\n  "verdict": "pass 或 fail",\n  "critic_verdict": "pass 或 fail 或 not_applicable",\n  "independent_verdict": "pass 或 fail",\n  "independent_direct_error": false,\n  "hard_rule_hit": false,\n  "applicable_critics": [],\n  "rules_hit": [],\n  "rubric_scores": {},\n  "normalized_score": null,\n  "evidence_coverage": 0.0,\n  "disagreement": false,\n  "reason": "一到两句话，指出直接证据；分歧时分别说明两条路径"\n}\n字段必须一致。independent_direct_error 只有在 reason 能定位具体矛盾或重算错误时\n才能为 true。不要把“未展示”“没写全”“无法核对”改写成已经成立的错误。\nEOF\n}\n'
