def git_blob_hash(data: bytes) -> str:
    header = f"blob {len(data)}\0".encode()
    return hashlib.sha1(header + data).hexdigest()


def repo_root() -> Path:
    p = subprocess.run(["git", "rev-parse", "--show-toplevel"], text=True,
                       stdout=subprocess.PIPE, stderr=subprocess.PIPE)
    if p.returncode != 0:
        raise SystemExit("请在 VeriSkill Git 仓库内运行。")
    return Path(p.stdout.strip()).resolve()


def replace_regex(text: str, pattern: str, replacement: str, label: str,
                  flags: int = re.M | re.S) -> str:
    out, count = re.subn(pattern, lambda _m: replacement, text, count=1, flags=flags)
    if count != 1:
        raise RuntimeError(f"{label}：预期匹配 1 次，实际 {count} 次")
    return out


def insert_after(text: str, anchor: str, block: str, marker: str, label: str) -> str:
    if marker in text:
        return text
    pos = text.find(anchor)
    if pos < 0:
        raise RuntimeError(f"{label}：找不到锚点 {anchor!r}")
    pos += len(anchor)
    return text[:pos] + block + text[pos:]


def transform(root: Path) -> tuple[dict[str, bytes], set[str]]:
    original = {}
    for rel in EXPECTED:
        p = root / rel
        if not p.is_file():
            raise RuntimeError(f"缺少基线文件：{rel}")
        original[rel] = p.read_bytes()

    # Exact baseline lock. If a file already contains our marker, it is accepted
    # as an idempotent rerun; otherwise all five hashes must match the user values.
    mismatches = []
    for rel, expected in EXPECTED.items():
        data = original[rel]
        if MARKER.encode() in data:
            continue
        actual = git_blob_hash(data)
        if actual != expected:
            mismatches.append(f"{rel}: expected {expected}, got {actual}")
    if mismatches:
        raise RuntimeError("基线哈希不匹配：\n  " + "\n  ".join(mismatches))

    updates: dict[str, bytes] = {}

    # lib/jsonx.py: replace exactly one complete function, independent of line numbers.
    rel = "lib/jsonx.py"
    text = original[rel].decode("utf-8")
    if MARKER not in text:
        text = replace_regex(
            text,
            r"^def build_verdict\(obj, item, threshold\):.*?(?=^class EnvFailure)",
            JSONX_FUNCTION + "\n# " + MARKER + "\n\n",
            rel,
        )
    updates[rel] = text.encode()

    # lib/pool.py: replace audit queue function and extend CLI.
    rel = "lib/pool.py"
    text = original[rel].decode("utf-8")
    if MARKER not in text:
        text = text.replace(
            "audit-queue 按两段制排出本轮审计队列（剔除已审组合）",
            "audit-queue 分层排出本轮审计队列（剔除已审组合与无真值条目）",
            1,
        )
        if "from pathlib import Path\n" not in text:
            if "import tempfile\n" not in text:
                raise RuntimeError(f"{rel}：找不到 pathlib 导入锚点")
            text = text.replace(
                "import tempfile\n",
                "import tempfile\nfrom pathlib import Path\n",
                1,
            )
        text = replace_regex(
            text,
            r"^def cmd_audit_queue\(a\):.*?(?=^# -+ main)",
            POOL_FUNCTION + "\n# " + MARKER + "\n",
            rel,
        )
        audit_cli = (
            '    p = sub.add_parser("audit-queue")\n'
            '    p.add_argument("--verdicts", required=True)\n'
            '    p.add_argument("--audited", required=True)\n'
            '    p.add_argument("--fingerprint", required=True)\n'
            '    p.add_argument("--budget", type=int, required=True)\n'
            '    p.add_argument("--round", type=int, required=True)\n'
        )
        if audit_cli not in text:
            raise RuntimeError(f"{rel}：找不到完整的 audit-queue 参数块")
        text = text.replace(
            audit_cli,
            audit_cli
            + '    p.add_argument("--checker-dir")\n'
            + '    p.add_argument("--truth-dir")\n'
            + '    p.add_argument("--allow-redo-as-truth", action="store_true")\n',
            1,
        )
    updates[rel] = text.encode()

    # oracle_run.sh: successful execution without truth becomes unscored.
    rel = "oracle_run.sh"
    text = original[rel].decode("utf-8")
    if MARKER not in text:
        fallback = ORACLE_FALLBACK
        text = replace_regex(
            text,
            r"^  # ---- 没有 checker/truth：.*?^  exit 0\n(?=\})",
            fallback + "  # " + MARKER + "\n",
            rel,
        )
        text = text.replace(
            "#      5  模型调用失败、输出解析不了、或模型自报执行环境故障\n",
            "#      5  模型调用失败、输出解析不了、或模型自报执行环境故障\n"
            "#      6  没有 checker/truth，无法得到可靠真值（不应重试）\n",
            1,
        )
    updates[rel] = text.encode()

    # verify.sh: replace whole prompt and worker function, then add static checks.
    rel = "verify.sh"
    text = original[rel].decode("utf-8")
    if MARKER not in text:
        text = replace_regex(
            text,
            r"^write_prompt\(\) \{.*?(?=^# -+ 判一条)",
            VERIFY_PROMPT + "\n# " + MARKER + "\n",
            rel + ":write_prompt",
        )
        text = replace_regex(
            text,
            r"^_verify_one_inner\(\) \{.*?(?=^# -+ selftest)",
            VERIFY_INNER + "\n",
            rel + ":worker",
        )
    updates[rel] = text.encode()

    # Keep the current launcher unchanged; its exact hash is checked above. The old
    # patch's launcher rewrite was operational, not required for calibration, and
    # was the most branch-specific hunk. Canonicalize only the divergent wrapper.
    updates["adapters/launch_loop_101.sh"] = original["adapters/launch_loop_101.sh"]

    rel = "run_rounds.sh"
    p = root / rel
    old = p.read_text(encoding="utf-8") if p.exists() else ""
    if MARKER not in old:
        if "launch_loop_101.sh" not in old and "VeriSkill" not in old:
            raise RuntimeError(f"{rel}：文件不像预期的旧入口，拒绝覆盖")
        text = RUN_ROUNDS + "# " + MARKER + "\n"
    else:
        text = old
    updates[rel] = text.encode()

    # Prompt-level process correction. We add one authoritative block rather than
    # line-fragile edits throughout the long documents.
    rel = ".claude/commands/veriskill-loop.md"
    text = (root / rel).read_text(encoding="utf-8")
    text = insert_after(text, "## 核心逻辑", COMMAND_PRIORITY,
                        "## v5 同样本校准规则", rel)
    updates[rel] = text.encode()

    rel = ".claude/agents/d-improve.md"
    text = (root / rel).read_text(encoding="utf-8")
    anchor = "判得更准。"
    text = insert_after(text, anchor, D_PRIORITY, "## v5 同样本监督", rel)
    updates[rel] = text.encode()

    rel = ".claude/agents/g-improve.md"
    text = (root / rel).read_text(encoding="utf-8")
    anchor = "但你写进技能的指引必须是可泛化的做法，不能是某道题的解法。"
    text = insert_after(text, anchor, G_PRIORITY, "## v5 当前轨迹监督", rel)
    updates[rel] = text.encode()

    created = set()
    for rel, b64 in NEW_FILES_B64.items():
        data = base64.b64decode(b64)
        p = root / rel
        if p.exists():
            if p.read_bytes() != data:
                raise RuntimeError(f"新文件目标已存在且内容不同：{rel}")
        else:
            created.add(rel)
        updates[rel] = data

    return updates, created


def write_all(root: Path, updates: dict[str, bytes], created: set[str]) -> None:
    backup = root / BACKUP_DIR
    if backup.exists():
        raise RuntimeError(f"备份目录已存在：{backup}。先运行 --restore 或删除它。")
    backup.mkdir(parents=True)
    manifest = []
    for rel in updates:
        src = root / rel
        if src.exists():
            dst = backup / rel
            dst.parent.mkdir(parents=True, exist_ok=True)
            shutil.copy2(src, dst)
            manifest.append(rel)
    (backup / "MANIFEST").write_text("\n".join(manifest) + "\n", encoding="utf-8")
    (backup / "CREATED").write_text("\n".join(sorted(created)) + "\n", encoding="utf-8")

    for rel, data in updates.items():
        p = root / rel
        p.parent.mkdir(parents=True, exist_ok=True)
        tmp = p.with_name(p.name + ".tmp-veriskill")
        tmp.write_bytes(data)
        if p.exists():
            os.chmod(tmp, stat.S_IMODE(p.stat().st_mode))
        elif rel.endswith(".sh") or rel.startswith("lib/") and data.startswith(b"#!"):
            os.chmod(tmp, 0o755)
        else:
            os.chmod(tmp, 0o644)
        os.replace(tmp, p)


def restore(root: Path) -> None:
    backup = root / BACKUP_DIR
    if not backup.exists():
        raise SystemExit("没有可恢复的备份目录。")
    manifest = (backup / "MANIFEST").read_text(encoding="utf-8").splitlines()
    created = (backup / "CREATED").read_text(encoding="utf-8").splitlines()
    for rel in created:
        p = root / rel
        if p.exists():
            p.unlink()
    for rel in manifest:
        src = backup / rel
        dst = root / rel
        dst.parent.mkdir(parents=True, exist_ok=True)
        shutil.copy2(src, dst)
    shutil.rmtree(backup)
    print("已恢复补丁前状态。")


def run_validation(root: Path) -> None:
    commands = [
        [sys.executable, "-c",
         "import ast,pathlib;[ast.parse(pathlib.Path(p).read_text(encoding='utf-8'), filename=p) "
         "for p in ['lib/jsonx.py','lib/pool.py','lib/trajectory_checks.py','lib/result_report.py']]"],
        ["bash", "-n", "verify.sh"],
        ["bash", "-n", "oracle_run.sh"],
        ["bash", "-n", "run_rounds.sh"],
        ["bash", "-n", "eval_final_same_sample.sh"],
        [sys.executable, "-m", "unittest", "discover", "-s", "tests", "-v"],
        ["git", "diff", "--check"],
    ]
    env = os.environ.copy()
    env["PYTHONDONTWRITEBYTECODE"] = "1"
    for cmd in commands:
        print("+", " ".join(cmd))
        subprocess.run(cmd, cwd=root, check=True, env=env)


def emit_diff(root: Path, out: Path, paths) -> None:
    fd, idx_name = tempfile.mkstemp(prefix="veriskill-index-")
    os.close(fd)
    os.unlink(idx_name)
    env = os.environ.copy()
    env["GIT_INDEX_FILE"] = idx_name
    try:
        subprocess.run(["git", "read-tree", "HEAD"], cwd=root, env=env, check=True)
        subprocess.run(["git", "add", "-A", "--", *sorted(paths)],
                       cwd=root, env=env, check=True)
        data = subprocess.check_output(
            ["git", "diff", "--cached", "--binary", "HEAD", "--", "."],
            cwd=root, env=env,
        )
        out = out if out.is_absolute() else root / out
        out.write_bytes(data)
        print(f"已生成精确普通补丁：{out}")
    finally:
        try:
            os.unlink(idx_name)
        except FileNotFoundError:
            pass


def main() -> None:
    ap = argparse.ArgumentParser()
    mode = ap.add_mutually_exclusive_group(required=True)
    mode.add_argument("--check", action="store_true", help="只验证哈希与全部替换锚点")
    mode.add_argument("--apply", action="store_true", help="原子应用并运行验证")
    mode.add_argument("--restore", action="store_true", help="恢复自动备份")
    ap.add_argument("--emit-diff", type=Path,
                    help="应用后从临时 Git index 导出包含新文件的普通 .patch")
    args = ap.parse_args()
    root = repo_root()
    if args.restore:
        restore(root)
        return

    updates, created = transform(root)
    print(f"基线与替换锚点检查通过：将更新 {len(updates)} 个文件，其中新建 {len(created)} 个。")
    if args.check:
        return

    try:
        write_all(root, updates, created)
        run_validation(root)
    except Exception:
        print("应用或验证失败，正在自动回滚……", file=sys.stderr)
        try:
            restore(root)
        except Exception as rollback_error:
            print(f"自动回滚失败：{rollback_error}", file=sys.stderr)
        raise
    if args.emit_diff:
        emit_diff(root, args.emit_diff, updates.keys())
    print("补丁已应用并通过验证。备份保留在", root / BACKUP_DIR)


if __name__ == "__main__":
    main()
